<?php
/** Actual composed writer and SQLite; metadata doubles are inherited explicitly. */
declare(strict_types=1);
require __DIR__.'/ticket_create.php';
$definition=NativeCompanyCustomFields::definition(['fieldto'=>'tickets','name'=>'Ticket reference','type'=>'input','required'=>1]);
$db->query('INSERT INTO tblcompany_custom_fields(issuer_id,fieldto,slug,definition_json,revision) VALUES(?,?,?,?,1)',[2,'tickets','ticket_ref',json_encode($definition,JSON_THROW_ON_ERROR)]);
