kc(array_column($tags,'label')===['Support','Native'],'same owned tag catalog and source links');
kc($service->createNative(2,17,$form,$key('decorated'))===$created,'decoration replay same receipt');
$snapshot=static fn()=>[$db->query('SELECT * FROM tblcompany_tickets ORDER BY id')->result_array(),$db->query('SELECT * FROM tblcompany_custom_field_values ORDER BY source_id')->result_array(),$db->query('SELECT * FROM tblcompany_work_tag_links ORDER BY source_id,tag_id')->result_array(),$db->query('SELECT * FROM tblcompany_ticket_requests ORDER BY request_key')->result_array()];
$before=$snapshot();$deny(fn()=>$service->createNative(2,17,$input,$key('required-missing')));kc($snapshot()===$before,'required field failure rolls back source, values, tags and receipt');
$db->query('INSERT INTO tblcompany_custom_fields(issuer_id,fieldto,slug,definition_json,revision) VALUES(?,?,?,?,1)',[3,'tickets','foreign_ref',json_encode($definition,JSON_THROW_ON_ERROR)]);$foreign=NativeCompanyResourceId::encode('company_custom_field',(int)$db->insert_id());
$deny(fn()=>$service->createNative(2,17,array_replace($form,['custom_fields'=>['tickets'=>[$foreign=>'private']]]),$key('foreign-field')));kc($snapshot()===$before,'foreign company field never accepted');
$deny(fn()=>$service->createNative(2,17,array_replace($form,['tags'=>'Duplicate, duplicate']),$key('duplicate-tags')));kc($snapshot()===$before,'invalid tags roll back earlier custom value');
$db->query("CREATE TRIGGER ticket_source_drift AFTER INSERT ON tblcompany_custom_field_values BEGIN UPDATE tblcompany_tickets SET subject='changed during composed write' WHERE id=NEW.source_id AND issuer_id=NEW.issuer_id; END");
$deny(fn()=>$service->createNative(2,17,$form,$key('source-drift')));$db->query('DROP TRIGGER ticket_source_drift');kc($snapshot()===$before,'private proof detects source mutation inside custom field write and rolls back');
$db->query("CREATE TRIGGER ticket_tag_fail BEFORE INSERT ON tblcompany_work_tag_links BEGIN SELECT RAISE(ABORT,'synthetic tag failure'); END");
try{$service->createNative(2,17,$form,$key('tag-write-failure'));throw new LogicException('tag write accepted');}catch(RuntimeException $e){kc($e->getMessage()==='issuer_storage_failed','tag SQL error fails transaction');}$db->query('DROP TRIGGER ticket_tag_fail');kc($snapshot()===$before,'tag SQL failure rolls back fields/source/receipt');
$deny(fn()=>(new NativeCompanyResourceTags($wrapped,'tbl'))->createTicketTagsInOwnedTransaction(2,17,$source,[],new stdClass()));
$deny(fn()=>(new NativeCompanyResourceTags($wrapped,'tbl'))->createTicketTagsInOwnedTransaction(2,17,$source,[],$service));
$fields=new NativeCompanyCustomFields($wrapped,'tbl');$deny(fn()=>IssuerTransaction::run($wrapped,'tbl',$fields->tableNames(),fn()=>$fields->saveCreatedInOwnedTransaction(2,17,'tickets',$source,[],$service)));
